package mz.bam.seeky.android;
import android.content.*;import android.os.*;import android.speech.tts.*;import android.widget.*;import java.io.*;import java.util.*;
/** Temporary selected-voice preview. It neither exports audio nor confirms voice settings. */
final class NarrationPreview {
 final ReaderActivity a;final SpeechProfile profile;final int part;final String selection;final boolean music;final Handler main=new Handler(Looper.getMainLooper());final long sleepGeneration=SleepTimer.fired;
 AmbientHold ambient;UiPanel panel;TextView status;TextToSpeech voice;ReadingBackground background;boolean closed,ready,loaded,started,restoreBackground;String text="",last="";
 NarrationPreview(ReaderActivity a,SpeechProfile profile,int part,String selection,boolean music){this.a=a;this.profile=profile;this.part=part;this.selection=selection;this.music=music;}
 void show(){if(a.preview!=null)a.preview.close();a.preview=this;panel=new UiPanel(a,"Prévia da narração",null,"speaker");status=a.text("A preparar o trecho…",14);panel.content.addView(status);TextView stop=a.button("Parar prévia",this::close);UiBox.style(stop);panel.content.addView(stop);panel.dismissed=this::close;panel.show();SpeechEvents.State state=SpeechEvents.state;if(state.active&&!state.paused)ReadAloudService.control(a,ReadAloudService.PAUSE,state.token);ambient=new AmbientHold(a);
  voice=SpeechEngines.create(a.getApplicationContext(),result->main.post(()->{if(closed)return;if(result!=TextToSpeech.SUCCESS){fail(new IOException("Motor de voz indisponível."));return;}ready=true;begin();}),profile.engine);
  a.worker.execute(()->{try{String value;if(selection!=null)value=selection;else try(SpeechDocument source=new SpeechDocument(a,a.uri,a.name,a.mime,()->closed||a.dead)){value=source.part(part);}int end=SpeechSeek.move(value,0,30000,profile.rate,SpeechLayout.of(value)).offset;if(end<=0)end=value.length();final String sample=value.substring(0,Math.min(value.length(),Math.min(end,6000)));main.post(()->{if(closed)return;text=sample;loaded=true;begin();});}catch(Exception|OutOfMemoryError e){main.post(()->fail(e));}});main.postDelayed(()->{if(!started&&!closed)fail(new IOException("A voz demorou demasiado. Tente outra voz ou verifique a ligação."));},90000);
 }
 void begin(){if(closed||started||!ready||!loaded)return;if(text.trim().isEmpty()){fail(new IOException("Não há texto para a prévia nesta parte."));return;}try{Voice selected=SpeechVoices.resolve(voice.getVoices(),profile.online,profile.language,profile.voice);if(selected==null)throw new IOException("Voz indisponível.");SpeechVoices.apply(voice,selected,profile.rate);SpeechVoices.verify(voice,profile);if(!ReadingAudioFocus.get(a).acquire(this,this::close))throw new IOException("Som ocupado por outra aplicação.");voice.setOnUtteranceProgressListener(new UtteranceProgressListener(){public void onStart(String id){main.post(()->{if(closed)return;if(!started){started=true;status.setText(AppLanguage.text(a,"A ouvir prévia · até 30 segundos"));main.postDelayed(NarrationPreview.this::close,30000);}});}public void onDone(String id){main.post(()->{if(id.equals(last))close();});}public void onError(String id){main.post(()->fail(new IOException("A voz não conseguiu reproduzir a prévia.")));}});if(music){background=new ReadingBackground(a,true);background.play();}SpeechLayout.Plan plan=SpeechLayout.of(text);List<PronunciationRules.Rule> rules=VoiceText.rules(a);int at=0,count=0;while(at<text.length()){int end=plan.end(at,Math.min(2200,TextToSpeech.getMaxSpeechInputLength()-1));end=VoiceText.fit(text,at,end,TextToSpeech.getMaxSpeechInputLength()-1,profile.language,rules);String chunk=VoiceText.prepare(text.substring(at,end),profile.language,rules).text;if(!chunk.trim().isEmpty()){String id="seeky-preview-"+(++count);last=id;if(voice.speak(chunk,count==1?TextToSpeech.QUEUE_FLUSH:TextToSpeech.QUEUE_ADD,SpeechParameters.create(profile.online),id)!=TextToSpeech.SUCCESS)throw new IOException("A voz recusou a prévia.");if(plan.pauseAfter(end)>0){String gap=id+"-gap";if(voice.playSilentUtterance(Math.max(500,Math.min(5000,a.getSharedPreferences("seeky",0).getInt("speech_title_pause_ms",2000))),TextToSpeech.QUEUE_ADD,gap)==TextToSpeech.SUCCESS)last=gap;}}at=end;}status.setText(AppLanguage.text(a,"A iniciar a voz…"));}catch(Exception e){fail(e);}}
 void fail(Throwable e){if(closed)return;close();if(!a.dead)PlusUi.error(a,e);}
 void close(){if(closed)return;closed=true;main.removeCallbacksAndMessages(null);if(a.preview==this)a.preview=null;if(voice!=null){try{voice.stop();}catch(RuntimeException ignored){}try{voice.shutdown();}catch(RuntimeException ignored){}voice=null;}if(background!=null){background.close();background=null;}ReadingAudioFocus.get(a).release(this);if(panel!=null&&panel.dialog.isShowing())panel.dialog.dismiss();if(ambient!=null)ambient.release();}
}
